
-- 1. Alo Yoga: The Sanctuary of the Streets
VALUES ('Alo Yoga: The Sanctuary of the Streets', 'From LA Streets to Global Mats', 'This is the story of two childhood friends from Los Angeles who looked at the yoga world and decided it wasn''t "cool" enough. A story of high-gloss celebrity culture, technical "street-to-studio" design, and how a brand named after the elements—Air, Land, and Ocean—conquered the pavement of Beverly Hills before it conquered the yoga mat.', '🧘', 'story', 'ladyboss-stories', '#E2F9F0', 'square', true, false, 30, 12, NULL);

